# Search for any jsonl files that might contain demo pairs
import os
import json

def find_jsonl_files(base_dir):
    results = []
    for root, dirs, files in os.walk(base_dir):
        for f in files:
            if f.endswith('.jsonl'):
                results.append(os.path.join(root, f))
    return results

